from pwn import *

def get_cookie(username):
    conn = remote('crypto.chal.csaw.io', 8000)
    conn.recvuntil(b'Enter your username (no whitespace): ')
    conn.sendline(username.encode())
    data = conn.recvline().strip().decode()
    if "Your Cookie is:" in data:
        cookie = data.split("Your Cookie is: ")[1]
        print(f"{username} cookie: {cookie}")
        return cookie
    else:
        print(f"Unexpected response for {username}: {data}")
        return None
    conn.close()

usernames = ['test1', 'test2', 'test3', 'admin', 'ADMIN', 'flag', 'a', 'aa', 'aaa', 'aaaa']
cookies = {}

for username in usernames:
    try:
        cookie = get_cookie(username)
        if cookie:
            cookies[username] = cookie
    except Exception as e:
        print(f"Error with {username}: {e}")
    time.sleep(1)  # Be nice to the server

print("\nCookie Analysis:")
for username, cookie in cookies.items():
    print(f"\n{username}: {cookie}")
    # Split into parts of 32 chars (potential blocks)
    parts = [cookie[i:i+32] for i in range(0, len(cookie), 32)]
    print(f"Length: {len(cookie)} characters")
    print(f"Parts: {len(parts)}")
    for i, part in enumerate(parts):
        print(f"Part {i+1}: {part}")

if len(cookies) >= 2:
    # Compare cookies to find common parts
    common_parts = []
    different_parts = []

    cookies_list = list(cookies.values())
    reference = cookies_list[0]

    parts_ref = [reference[i:i+32] for i in range(0, len(reference), 32)]

    for i, part_ref in enumerate(parts_ref):
        is_common = True
        for cookie in cookies_list[1:]:
            parts = [cookie[i:i+32] for i in range(0, len(cookie), 32)]
            if i >= len(parts) or parts[i] != part_ref:
                is_common = False
                break

        if is_common:
            common_parts.append((i, part_ref))
        else:
            different_parts.append((i, part_ref))

    print("\nCommon parts across all cookies:")
    for idx, part in common_parts:
        print(f"Block {idx+1}: {part}")

    print("\nDifferent parts:")
    for idx, part in different_parts:
        print(f"Block {idx+1}: {part}")

from pwn import *
import binascii

def get_cookie(username):
    conn = remote('crypto.chal.csaw.io', 8000)
    conn.recvuntil(b'Enter your username (no whitespace): ')
    conn.sendline(username.encode())
    data = conn.recvline().decode().strip()
    cookie = data.split("Your Cookie is: ")[1]
    conn.close()
    return cookie

# Collect multiple cookies for analysis
usernames = ["test1", "test2", "admin", "aaaaaaaa", "bbbbbbbb", "secret", "user123", "ABCDEF"]
cookies = {}

for username in usernames:
    try:
        cookies[username] = get_cookie(username)
        print(f"{username}: {cookies[username]}")
    except Exception as e:
        print(f"Error getting cookie for {username}: {e}")

# All cookies seem to have the same length (96 hex chars = 48 bytes)
print("\n=== Length Analysis ===")
for username, cookie in cookies.items():
    print(f"{username}: {len(cookie)} chars ({len(cookie)//2} bytes)")

# Split each cookie into 16-byte chunks
print("\n=== Block Analysis ===")
for username, cookie in cookies.items():
    blocks = [cookie[i:i+32] for i in range(0, len(cookie), 32)]
    print(f"{username}: {blocks}")

# Compare cookies of usernames with the same length
print("\n=== Same Length Username Comparison ===")
username_by_length = {}
for username in usernames:
    if len(username) not in username_by_length:
        username_by_length[len(username)] = []
    username_by_length[len(username)].append(username)

for length, same_length_usernames in username_by_length.items():
    if len(same_length_usernames) > 1:
        print(f"\nUsernames of length {length}:")
        for i, username1 in enumerate(same_length_usernames):
            if username1 not in cookies:
                continue
            for username2 in same_length_usernames[i+1:]:
                if username2 not in cookies:
                    continue

                cookie1 = cookies[username1]
                cookie2 = cookies[username2]

                # Create a match pattern
                match_pattern = ''.join(['=' if a == b else '.' for a, b in zip(cookie1, cookie2)])

                print(f"Comparing {username1} vs {username2}:")
                print(f"  {username1}: {cookie1}")
                print(f"  {username2}: {cookie2}")
                print(f"  Match:     {match_pattern}")

                # Count matching parts
                matches = sum(1 for a, b in zip(cookie1, cookie2) if a == b)
                print(f"  Matching characters: {matches}/{len(cookie1)} ({matches/len(cookie1)*100:.1f}%)")

                # Check if there are identical blocks
                blocks1 = [cookie1[i:i+32] for i in range(0, len(cookie1), 32)]
                blocks2 = [cookie2[i:i+32] for i in range(0, len(cookie2), 32)]

                for j, (block1, block2) in enumerate(zip(blocks1, blocks2)):
                    if block1 == block2:
                        print(f"  Block {j} is identical: {block1}")

# Check for cookie generation consistency (deterministic vs non-deterministic)
print("\n=== Determinism Test ===")
for test_name in ["test1", "admin"]:
    cookies_list = []
    for i in range(3):
        cookies_list.append(get_cookie(test_name))

    if all(cookie == cookies_list[0] for cookie in cookies_list):
        print(f"{test_name}: DETERMINISTIC (all 3 cookies are identical)")
    else:
        print(f"{test_name}: NON-DETERMINISTIC")
        for i, cookie in enumerate(cookies_list):
            print(f"  Cookie {i+1}: {cookie}")

        # Generate pattern to see which parts change
        if len(cookies_list) >= 2:
            pattern = ""
            for i in range(len(cookies_list[0])):
                unique_chars = set(cookie[i] for cookie in cookies_list)
                pattern += "=" if len(unique_chars) == 1 else "."
            print(f"  Change pattern: {pattern}")

# Check for consistent blocks across different usernames
print("\n=== Cross-Username Block Analysis ===")
block_values = [set() for _ in range(3)]  # Assuming 3 blocks of 32 chars each

for username, cookie in cookies.items():
    blocks = [cookie[i:i+32] for i in range(0, len(cookie), 32)]
    for i, block in enumerate(blocks):
        block_values[i].add(block)

for i, values in enumerate(block_values):
    if len(values) == 1:
        print(f"Block {i} is CONSTANT across all usernames: {next(iter(values))}")
    else:
        print(f"Block {i} VARIES across usernames (unique values: {len(values)})")
        if i == 1 or i == 2:  # Only show all values for smaller sets
            print(f"  Values: {values}")

# Check if the second part of the cookie is consistent
print("\n=== Second Half Consistency Check ===")
second_halves = set()
for username, cookie in cookies.items():
    midpoint = len(cookie) // 2
    second_half = cookie[midpoint:]
    second_halves.add(second_half)

if len(second_halves) == 1:
    print(f"The second half of all cookies is IDENTICAL: {next(iter(second_halves))}")
else:
    print(f"The second half varies: {len(second_halves)} different values")

# Try to analyze cookie format: check if there's a potential MAC or signature
print("\n=== Format Analysis ===")
for username in ["test1", "admin"]:
    if username in cookies:
        cookie = cookies[username]
        cookie_bytes = binascii.unhexlify(cookie)
        print(f"{username} cookie bytes (length: {len(cookie_bytes)})")

        # Check various potential divisions (12+36, 16+32, 24+24, etc.)
        for first_part_size in [12, 16, 20, 24, 32]:
            if len(cookie_bytes) >= first_part_size:
                first_part = cookie_bytes[:first_part_size]
                second_part = cookie_bytes[first_part_size:]
                print(f"  Split at {first_part_size} bytes:")
                print(f"    First part ({len(first_part)} bytes): {binascii.hexlify(first_part).decode()}")
                print(f"    Second part ({len(second_part)} bytes): {binascii.hexlify(second_part).decode()}")
